{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history shows low positive sentiment (e.g., 0.00) and model overestimates prices.",
    "Reduce forecast magnitude after a sharp price spike; avoid overshoot by applying a 10-15% downward correction if true outcome is below forecast.",
    "If true outcome is consistently lower than forecast over 5+ days, apply mean reversion by averaging recent 5-day true values and adjust forecast toward that mean.",
    "When sentiment history includes a 0.67 or higher value, increase forecast sensitivity to recent price trends, but cap upward adjustments at +10% to avoid overcorrection.",
    "For horizon > 15 days, apply a lag correction: if true outcome is below forecast, reduce forecast by 5-10% for the next 3 days to account for delayed market reaction.",
    "If forecast consistently exceeds true outcome by >10% over 3 consecutive days, apply a downward bias correction of 5-8% per day until convergence."
  ]
}
